sys_variable_value.value:
(function execute(inputs, outputs) {
    var pr = inputs.priority;
    var result;
    switch (pr) {
        case "p0": result = 1;
            break;
        case "p1": result = 2;
            break;
        case "p2": result = 3;
            break;
        default: result = 4;
    }
    outputs.internal_priority = result;
    
})(inputs, outputs);

